#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/sys/util.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)

static K_THREAD_STACK_DEFINE(thread_low_stack, STACK_SIZE);
static K_THREAD_STACK_DEFINE(thread_mid_stack, STACK_SIZE);
static K_THREAD_STACK_DEFINE(thread_high_stack, STACK_SIZE);

static struct k_thread thread_low;
static struct k_thread thread_mid;
static struct k_thread thread_high;

static K_MUTEX_DEFINE(mutex1);
static K_MUTEX_DEFINE(mutex2);

static K_SEM_DEFINE(sem_low_done, 0, 1);
static K_SEM_DEFINE(sem_mid_done, 0, 1);
static K_SEM_DEFINE(sem_high_done, 0, 1);

static K_SEM_DEFINE(sem_low_start, 0, 1);
static K_SEM_DEFINE(sem_mid_start, 0, 1);
static K_SEM_DEFINE(sem_high_start, 0, 1);

#define THREAD_LOW_PRIO 5
#define THREAD_MID_PRIO 4
#define THREAD_HIGH_PRIO 3

/*
 * This test is for a more complex priority inversion scenario:
 *
 * Thread Low: 5
 * Thread Mid: 4
 * Thread High: 3
 *
 * 1. Low takes mutex1
 * 2. High starts, pends on mutex1, boosts Low to 3
 * 3. Mid starts, pends on mutex2
 * 4. Low takes mutex2, should now be running
 * 5. Low releases mutex1, High gets it and runs. Low's priority
 *    is recalculated to 4 because Mid is waiting on mutex2.
 * 6. High releases mutex1, its priority drops back to 3.
 * 7. Low releases mutex2, Mid gets it and runs. Low's priority
 *    is restored to 5.
 * 8. Mid releases mutex2, its priority drops back to 4.
 * 9. All threads finish.
 *
 * This tests that when a thread holds more than one mutex, its
 * priority is determined by the highest priority thread waiting
 * on any of the mutexes it holds. It also tests that when it
 * releases a mutex, its priority is re-calculated based on the
 * remaining mutexes it holds.
 */

static void thread_low_entry(void *p1, void *p2, void *p3)
{
	k_sem_take(&sem_low_start, K_FOREVER);

	/* 1. Low takes mutex1 */
	zassert_ok(k_mutex_lock(&mutex1, K_FOREVER), "Low failed to take mutex1");

	/* Let High run and pend on mutex1 */
	k_sem_give(&sem_high_start);
	k_msleep(100); /* Give time for High to run and block */

	/*
	 * At this point, Low should have its priority boosted to 3 by High.
	 * Let Mid run and pend on mutex2.
	 */
	k_sem_give(&sem_mid_start);
	k_msleep(100); /* Give time for Mid to run and block */

	/*
	 * 4. Low takes mutex2. Since Low is running at priority 3 (boosted),
	 * it should preempt Mid (prio 4) and get the mutex.
	 */
	zassert_ok(k_mutex_lock(&mutex2, K_FOREVER), "Low failed to take mutex2");

	/*
	 * 5. Low releases mutex1. High will unpend, get the mutex, and
	 * start running. Low's priority should drop. Since it still holds
	 * mutex2, which Mid is waiting on, its priority should be boosted
	 * to 4.
	 */
	k_mutex_unlock(&mutex1);
	zassert_equal(k_thread_priority_get(&thread_low), THREAD_MID_PRIO,
		      "Low prio not boosted by Mid");

	/*
	 * 7. Low releases mutex2. Mid will unpend and run. Low's priority
	 * should drop back to its original priority.
	 */
	k_mutex_unlock(&mutex2);
	zassert_equal(k_thread_priority_get(&thread_low), THREAD_LOW_PRIO,
		      "Low prio not back to original");

	k_sem_give(&sem_low_done);
}

static void thread_mid_entry(void *p1, void *p2, void *p3)
{
	k_sem_take(&sem_mid_start, K_FOREVER);

	/* 3. Mid starts, pends on mutex2 */
	zassert_ok(k_mutex_lock(&mutex2, K_FOREVER), "Mid failed to take mutex2");

	/* 8. Mid releases mutex2 */
	k_mutex_unlock(&mutex2);

	k_sem_give(&sem_mid_done);
}

static void thread_high_entry(void *p1, void *p2, void *p3)
{
	k_sem_take(&sem_high_start, K_FOREVER);

	/* 2. High starts, pends on mutex1, boosts Low to 3 */
	zassert_ok(k_mutex_lock(&mutex1, K_FOREVER), "High failed to take mutex1");

	/* 6. High releases mutex1 */
	k_mutex_unlock(&mutex1);

	k_sem_give(&sem_high_done);
}

/**
 * @brief Test complex priority inversion scenario.
 *
 * This test verifies that a thread holding multiple mutexes has its priority
 * correctly adjusted based on the highest priority thread waiting on any of
 * the mutexes it holds.
 *
 * @see k_mutex_lock(), k_mutex_unlock()
 *
 * @ingroup kernel_mutex_tests
 */
ZTEST(mutex_api, test_mutex_complex_priority_inversion)
{
	k_thread_create(&thread_low, thread_low_stack, STACK_SIZE,
			thread_low_entry, NULL, NULL, NULL,
			THREAD_LOW_PRIO, 0, K_NO_WAIT);

	k_thread_create(&thread_mid, thread_mid_stack, STACK_SIZE,
			thread_mid_entry, NULL, NULL, NULL,
			THREAD_MID_PRIO, 0, K_NO_WAIT);

	k_thread_create(&thread_high, thread_high_stack, STACK_SIZE,
			thread_high_entry, NULL, NULL, NULL,
			THREAD_HIGH_PRIO, 0, K_NO_WAIT);

	/* Let Low run first to grab mutex1 */
	k_sem_give(&sem_low_start);
	k_msleep(100); /* Give time for Low to run and take mutex1 */

	/* Wait for all threads to complete */
	zassert_ok(k_sem_take(&sem_low_done, K_MSEC(1000)), "Low did not finish");
	zassert_ok(k_sem_take(&sem_mid_done, K_MSEC(1000)), "Mid did not finish");
	zassert_ok(k_sem_take(&sem_high_done, K_MSEC(1000)), "High did not finish");

	/* Clean up */
	k_thread_abort(&thread_low);
	k_thread_abort(&thread_mid);
	k_thread_abort(&thread_high);
}
